<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantConfig\Domain\ValueObject\Accessor\TenantConfigAcrValuesSupportedAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantConfigAcrValuesSupportedAccessor trait.
 *
 * Covers null default, string/VO assignment via withAcrValuesSupported,
 * getAcrValuesSupported/acrValuesSupported accessors, and isAcrValuesSupportedChanged with/without original.
 */
class TenantConfigAcrValuesSupportedAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withAcrValuesSupported creates a new instance with the AcrValuesSupported set
     * from a string value, and getAcrValuesSupported returns the primitive string.
     */
    public function testWithAcrValuesSupportedFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigAcrValuesSupportedAccessorUnitTest();

        // Act
        $result = $holder->withAcrValuesSupported('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getAcrValuesSupported());
    }
    /**
     * Asserts that withacrValuesSupported has access to the value object
     * from a string value, and getAcrValuesSupported returns the primitive string.
     */
    public function testWithAcrValuesSupportedFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigAcrValuesSupportedAccessorUnitTest();

        // Act
        $result = $holder->withAcrValuesSupported('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->acrValuesSupported()->value());
    }
    public function testChangedAcrValuesSupported(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigAcrValuesSupportedAccessorUnitTest();
        $original = $holder->withAcrValuesSupported('one');
        $same = $holder->withAcrValuesSupported('one');
        $modified = $holder->withAcrValuesSupported('other');

        // Act
        $unchanged = $holder->isAcrValuesSupportedChanged();
        $withSame = $original->isAcrValuesSupportedChanged($same);
        $withDiferent = $original->isAcrValuesSupportedChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantConfigAcrValuesSupportedAccessorUnitTest
{
    use TenantConfigAcrValuesSupportedAccessor;
}
